// Versioned learning state. Content and SQLite engine remain independent.
const STAGES=['understand','practice','review','complete'];
const REVIEW_DAYS=[1,3,7,21];
const freshDataMutation="UPDATE customers SET city='Chicago' WHERE id=2; UPDATE products SET price=price+3; UPDATE orders SET quantity=quantity+1 WHERE id=101; UPDATE watch_events SET watch_seconds=watch_seconds+30 WHERE id=1; UPDATE ai_requests SET input_tokens=input_tokens+100 WHERE id=1; UPDATE bronze_sales SET quantity='4' WHERE row_id=1; UPDATE fact_sales SET quantity=4,sales=48 WHERE sale_key=1; UPDATE product_versions SET cost=cost+2;";
function cleanStats(stats,version){const out={};if(!stats||typeof stats!=='object'||Array.isArray(stats))return out;for(const [id,r] of Object.entries(stats)){if(!lessons[+id]||!r||typeof r!=='object')continue;out[id]={attempts:Math.max(0,+r.attempts||0),correct:Math.max(0,+r.correct||0),solved:[...new Set((Array.isArray(r.solved)?r.solved:[]).filter(x=>x===0||x===1))],last:+r.last||0,errors:Math.max(0,+r.errors||0),check:r.check===true,legacy:r.legacy===true||version!==2&&version!==3&&r.solved?.length>=2,masteredAt:+r.masteredAt||0,categories:r.categories&&typeof r.categories==='object'?r.categories:{},quizAttempts:Math.max(0,+r.quizAttempts||0)};}return out;}
function migrateLearning(input={}){const data={version:3,stats:cleanStats(input.stats,input.version),history:Array.isArray(input.history)?input.history.filter(h=>lessons[h.id]&&typeof h.ok==='boolean').slice(-300):[],drafts:{},attempts:{},sessions:{},projects:{},reviews:{},preferences:{theme:'system',collapsed:false},active:null,lastProject:null,placement:null};for(const key of ['drafts','attempts','sessions','projects','reviews'])if(input.version===3&&input[key]&&typeof input[key]==='object'&&!Array.isArray(input[key]))data[key]=input[key];if(input.preferences&&['system','light','dark'].includes(input.preferences.theme))data.preferences={theme:input.preferences.theme,collapsed:input.preferences.collapsed===true};if(input.version===3&&input.active&&lessons[input.active.id]&&STAGES.includes(input.active.stage))data.active={id:input.active.id,variant:input.active.variant===1?1:0,stage:input.active.stage,project:Number.isInteger(input.active.project)&&caseStudyGroups[input.active.project]?input.active.project:null};else if(Number.isInteger(input.id)&&lessons[input.id]&&(Object.keys(data.stats).length||input.version===2))data.active={id:input.id,variant:data.stats[input.id]?.solved.includes(0)?1:0,stage:'understand',project:null};if(input.version===3){data.lastProject=caseStudyGroups[input.lastProject]?input.lastProject:null;data.placement=input.placement||null;}for(const [id,r] of Object.entries(data.stats))if(r.solved.length===2&&(r.check||r.legacy)&&!data.reviews[id])data.reviews[id]={level:0,due:(r.last||Date.now())+86400000,history:[]};if(input.version!==3)caseStudyGroups.forEach((c,pid)=>{const done=c.ids.filter(id=>{const r=data.stats[id];return r?.solved.length===2&&(r.check||r.legacy)});if(done.length){data.projects[pid]={started:Math.min(...done.map(id=>data.stats[id].last||Date.now())),last:done[0],migrated:true,milestones:Object.fromEntries(done.map(id=>[id,{solved:[0,1],check:data.stats[id].check,legacy:data.stats[id].legacy===true,queries:{},results:{},updated:data.stats[id].last||0}]))};}});normalizeLearning(data);return data;}
function normalizeLearning(data){
 for(const [key,value] of Object.entries(data.drafts))if(typeof value!=='string'||value.length>200000)delete data.drafts[key];
 for(const [key,a] of Object.entries(data.attempts)){if(!a||typeof a!=='object'||!Array.isArray(a.exposures)){delete data.attempts[key];continue;}data.attempts[key]={guided:a.guided===true,hints:Math.min(3,Math.max(0,+a.hints||0)),revealed:a.revealed===true,fresh:a.fresh===true,epoch:Math.max(0,+a.epoch||0),exposures:a.exposures.slice(-100)};}
 for(const [key,s] of Object.entries(data.sessions)){if(!s||typeof s!=='object'||!key.startsWith('activity:')&&!STAGES.includes(s.stage))delete data.sessions[key];else s.variant=s.variant===1?1:0;}
 for(const [pid,p] of Object.entries(data.projects)){if(!caseStudyGroups[+pid]||!p||typeof p!=='object'){delete data.projects[pid];continue;}if(!p.milestones||typeof p.milestones!=='object')p.milestones={};for(const [id,m] of Object.entries(p.milestones)){if(!caseStudyGroups[+pid].ids.includes(+id)||!m||typeof m!=='object'){delete p.milestones[id];continue;}m.solved=[...new Set((Array.isArray(m.solved)?m.solved:[]).filter(x=>x===0||x===1))];m.check=m.check===true;m.queries=m.queries&&typeof m.queries==='object'?m.queries:{};m.results=m.results&&typeof m.results==='object'?m.results:{};for(const [v,r] of Object.entries(m.results))if(!r||!Array.isArray(r.columns)||!Array.isArray(r.values)||r.values.some(row=>!Array.isArray(row)))delete m.results[v];for(const [v,q] of Object.entries(m.queries))if(typeof q!=='string')delete m.queries[v];}p.last=caseStudyGroups[+pid].ids.includes(p.last)?p.last:caseStudyGroups[+pid].ids[0];}
 for(const [id,r] of Object.entries(data.reviews)){if(!lessons[+id]||!r||typeof r!=='object'||!Number.isFinite(+r.due)){delete data.reviews[id];continue;}r.due=+r.due;r.step=Math.max(0,Math.min(3,+r.step||0));r.history=Array.isArray(r.history)?r.history.slice(-30):[];}
 if(data.placement){const p=data.placement;if(!Array.isArray(p.answers))data.placement=null;else{p.answers=p.answers.slice(0,6).map(a=>({ok:a?.ok===true,time:+a?.time||0}));p.index=Math.max(0,Math.min(6,+p.index||0));p.done=p.done===true&&p.index===6;}}
}
let learning=migrateLearning(saved);
// Recover V1/V2 session drafts without deleting the original storage keys.
try{for(const l of lessons)for(let v=0;v<2;v++){const key=`sql-draft-${l.id}-${v}`,draft=sessionStorage.getItem(key);if(draft&&!learning.drafts[key])learning.drafts[key]=draft;}for(const ds of Object.keys(datasetCatalog)){const key='sql-playground-'+ds,draft=sessionStorage.getItem(key);if(draft&&!learning.drafts[key])learning.drafts[key]=draft;}const lab=sessionStorage.getItem('sql-lab-script');if(lab&&!learning.drafts['sql-lab-script'])learning.drafts['sql-lab-script']=lab;}catch(e){}
state.stats=learning.stats;state.history=learning.history;state.stage='understand';state.started=!!learning.active;state.page='home';state.schemaOpen=false;state.helpOpen=false;state.routeModule=null;state.projectView=null;state.filterLevel='all';state.filterStatus='all';state.execution=null;state.exampleResult=null;state.placementIndex=0;state.placementAnswers=[];state.reviewChoice=null;state.reviewResult=null;state.runSerial=0;
function safePersist(){learning.stats=state.stats;learning.history=state.history.slice(-300);try{localStorage.setItem(KEY,JSON.stringify(learning));storageOK=true}catch(e){storageOK=false}}
save=safePersist;
const oldDraftKey=draftKey;
draftKey=function(){if(state.page==='assessment')return 'sql-placement-'+state.placementIndex;if(state.page==='practice'&&state.caseId!==null)return `sql-project-${state.caseId}-${state.id}-${state.variant}`;return oldDraftKey();};
function attemptKey(id=state.id,v=state.variant,project=state.caseId){return `${project===null?'lesson':'project-'+project}:${id}:${v}`;}
function attempt(){const key=attemptKey();return learning.attempts[key]||(learning.attempts[key]={guided:false,hints:0,revealed:false,fresh:false,epoch:0,exposures:[]});}
persistDraft=function(){const key=draftKey();learning.drafts[key]=state.query;try{sessionStorage.setItem(key,state.query);if(state.page==='lab')sessionStorage.setItem('sql-lab-dataset',state.dataset)}catch(e){}if(state.page==='practice'){learning.active={id:state.id,variant:state.variant,stage:state.stage,project:state.caseId};learning.sessions[attemptKey()]={stage:state.stage,variant:state.variant};learning.sessions['activity:'+state.caseId+':'+state.id]={variant:state.variant};}safePersist();};
function dueReviews(){return lessons.filter(l=>mastered(l.id)&&learning.reviews[l.id]?.due<=Date.now());}
reviewDue=dueReviews;
function projectRecord(pid){return learning.projects[pid]||(learning.projects[pid]={started:Date.now(),milestones:{},last:caseStudyGroups[pid].ids[0]});}
function milestoneRecord(pid,id){const p=projectRecord(pid);return p.milestones[id]||(p.milestones[id]={solved:[],check:false,queries:{},results:{},updated:0});}
function milestoneDone(pid,id){const r=learning.projects[pid]?.milestones[id];return !!r&&r.solved?.length===2&&(r.check===true||r.legacy===true);}
function projectDone(pid){return caseStudyGroups[pid].ids.every(id=>milestoneDone(pid,id));}
function moduleMetrics(g){const ls=courseOrder.map(id=>lessons[id]).filter(l=>l.group===g),done=ls.filter(l=>mastered(l.id)).length,touched=ls.filter(l=>record(l.id).attempts||learning.active?.id===l.id).length;return {ls,done,touched,status:done===ls.length?'Mastered':dueReviews().some(l=>l.group===g)?'Review due':touched?'In progress':'Not started'};}
function lessonStatus(id){if(dueReviews().some(l=>l.id===id))return 'Review recommended';if(mastered(id))return 'Mastered';if(!record(id).solved.length&&state.history.some(h=>h.id===id&&h.guided))return 'Guided practice';if(record(id).solved.length||record(id).attempts||learning.active?.id===id)return 'In progress';return 'Not started';}
function recommendedActivity(){const a=learning.active;if(a&&a.stage!=='complete'&&(a.project!==null?!milestoneDone(a.project,a.id):!mastered(a.id)))return {id:a.id,project:a.project,reason:'Continue your active lesson from the saved stage.',kind:'resume'};const weak=lessons.filter(l=>record(l.id).errors>=2&&!mastered(l.id)).sort((a,b)=>record(b.id).errors-record(a.id).errors);if(weak.length){const l=weak[0],p=l.prereq?.find(id=>!mastered(id));return {id:p??l.id,project:null,reason:p!==undefined?'Strengthen a prerequisite after repeated difficulties.':'Revisit a concept after repeated unsuccessful checks.',kind:'lesson'};}const due=dueReviews().sort((a,b)=>learning.reviews[a.id].due-learning.reviews[b.id].due);if(due.length)return {id:due[0].id,project:null,reason:'A spaced review is due. Your original mastery stays recorded.',kind:'review'};const unfinished=courseOrder.find(id=>record(id).attempts&&!mastered(id));if(unfinished!==undefined)return {id:unfinished,project:null,reason:'Finish a concept you have already practiced.',kind:'lesson'};for(let p=0;p<caseStudyGroups.length;p++){const c=caseStudyGroups[p];if(!projectDone(p)&&c.ids.slice(0,2).every(id=>mastered(id)))return {id:c.ids.find(id=>!milestoneDone(p,id)),project:p,reason:'Apply concepts you have mastered in a guided project.',kind:'project'};}const next=courseOrder.find(id=>!mastered(id));return {id:next??0,project:null,reason:next===undefined?'Revisit your work or explore a project.':'Build the next concept in the course roadmap.',kind:'lesson'};}
recommendation=()=>recommendedActivity().id;
function guidance(kind){const a=attempt();a.guided=true;if(kind==='hint')a.hints=Math.min(3,a.hints+1);else a.revealed=true;a.exposures.push({kind,time:Date.now(),epoch:a.epoch});state.assisted=true;safePersist();}
function classifyFailure(data){if(data.error)return /no such|ambiguous|syntax/i.test(data.error)?'SQL syntax or schema':'Execution';const m=data.grade?.message||'';return /column/i.test(m)?'Output columns':/rows; got/i.test(m)?'Row count':/order/i.test(m)?'Ordering':/constraint|object|CREATE|INSERT|UPDATE/i.test(m)?'Database contract':data.grade?.variationFailed?'Changed data':'Values or relationships';}
function scheduleMastery(id){const r=record(id);if(mastered(id)&&!r.masteredAt){r.masteredAt=Date.now();learning.reviews[id]={level:0,due:Date.now()+86400000,history:[]};}}
update=function(ok,guided,id,variant,category=null){const r=record(id);r.attempts++;r.correct+=ok?1:0;r.errors=ok?0:r.errors+1;r.last=Date.now();if(ok&&!guided&&!r.solved.includes(variant))r.solved.push(variant);if(!ok&&category)r.categories={...r.categories,[category]:(r.categories?.[category]||0)+1};state.stats[id]=r;state.history.push({id,variant,ok,guided,category,time:Date.now(),project:state.caseId});scheduleMastery(id);safePersist();};
function freshAttempt(){const a=attempt();if(a.guided||a.revealed){a.epoch++;a.fresh=true;}a.guided=false;a.hints=0;a.revealed=false;state.assisted=false;state.hint=0;state.result=null;state.expected=null;state.feedback=null;state.execution=null;state.query=starter(state.id);state.stage='practice';persistDraft();render();}
function completeQuiz(choice){const q=quizFor(state.id),r=record();state.quizChoice=choice;r.quizAttempts=(r.quizAttempts||0)+1;if(choice===q.correct){r.check=true;if(state.caseId!==null)milestoneRecord(state.caseId,state.id).check=true;}else r.errors++;r.last=Date.now();state.stats[state.id]=r;scheduleMastery(state.id);if(choice===q.correct&&(state.caseId!==null?milestoneDone(state.caseId,state.id):mastered(state.id)))state.stage='complete';persistDraft();render();}
function recordProject(ok,guided,result){if(state.caseId===null)return;const r=milestoneRecord(state.caseId,state.id);r.queries[state.variant]=state.query;r.results[state.variant]={ok,guided,columns:result?.columns||[],values:result?.values?.slice(0,20)||[],time:Date.now()};if(ok&&!guided&&!r.solved.includes(state.variant))r.solved.push(state.variant);r.updated=Date.now();projectRecord(state.caseId).last=state.id;learning.lastProject=state.caseId;safePersist();}
function ownSolves(){return state.caseId!==null?milestoneRecord(state.caseId,state.id).solved:record().solved;}
function exportData(){return {...learning,stats:state.stats,history:state.history,exported_at:new Date().toISOString()};}
function importLearning(data){if(data?.version!==undefined&&![1,2,3].includes(data.version))throw Error('Unsupported progress version.');if(!data||!data.stats||typeof data.stats!=='object'||Array.isArray(data.stats))throw Error('This is not a SQL Studio progress file.');if(data.version===3){for(const key of ['drafts','attempts','sessions','projects','reviews'])if(data[key]!==undefined&&(!data[key]||typeof data[key]!=='object'||Array.isArray(data[key])))throw Error('Invalid '+key+' records.');if(Object.values(data.attempts||{}).some(a=>!a||typeof a!=='object'||!Array.isArray(a.exposures)))throw Error('Invalid guidance history.');if(Object.values(data.sessions||{}).some(s=>!s||typeof s!=='object'))throw Error('Invalid lesson sessions.');if(Object.values(data.reviews||{}).some(r=>!r||typeof r!=='object'||!Number.isFinite(+r.due)))throw Error('Invalid review schedule.');if(Object.values(data.drafts||{}).some(v=>typeof v!=='string'||v.length>200000))throw Error('Invalid SQL drafts.');for(const [p,r] of Object.entries(data.projects||{})){if(!caseStudyGroups[+p]||!r||typeof r.milestones!=='object')throw Error('Invalid project record.');for(const [id,m] of Object.entries(r.milestones)){if(!caseStudyGroups[+p].ids.includes(+id)||!Array.isArray(m.solved)||m.solved.some(v=>v!==0&&v!==1))throw Error('Invalid project milestone.');}}}learning=migrateLearning(data);state.stats=learning.stats;state.history=learning.history;state.started=!!learning.active;safePersist();}
